import sys
import re
from bs4 import BeautifulSoup

def clean_html(html_content):
    soup = BeautifulSoup(html_content, 'html.parser')

    for script in soup.find_all('script'):
        script.decompose()

    for tag in soup.find_all(True):
        attrs_to_remove = []
        for attr, value in tag.attrs.items():
            attr_lower = attr.lower()

            if attr_lower.startswith('on'):
                attrs_to_remove.append(attr)
                continue

            if isinstance(value, list):
                val_str = ' '.join(map(str, value))
            else:
                val_str = str(value)

            val_str_clean = re.sub(r'[\x00-\x20\x7f-\x9f]', '', val_str).lower()

            if val_str_clean.startswith('javascript:') or val_str_clean.startswith('vbscript:'):
                attrs_to_remove.append(attr)
                continue

            if attr_lower == 'style':
                if 'javascript:' in val_str_clean or 'expression(' in val_str_clean:
                    attrs_to_remove.append(attr)
                    continue

        for attr in attrs_to_remove:
            del tag[attr]

    return str(soup)

def main():
    if len(sys.argv) != 2:
        print("Usage: python filter.py <file.html>")
        sys.exit(1)

    file_path = sys.argv[1]

    with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
        content = f.read()

    cleaned = clean_html(content)

    with open(file_path, 'w', encoding='utf-8') as f:
        f.write(cleaned)

if __name__ == '__main__':
    main()
