import pty
import os
import time
import threading
import signal
from base_terminal import BaseTerminal

class HeadlessTerminal(BaseTerminal):
    def __init__(self):
        self.pid, self.fd = pty.fork()
        if self.pid == 0:
            os.environ['TERM'] = 'xterm'
            os.execlp("bash", "bash")

        self.running = True
        self.thread = threading.Thread(target=self._reader, daemon=True)
        self.thread.start()
        time.sleep(0.5)

    def _reader(self):
        while self.running:
            try:
                data = os.read(self.fd, 4096)
                if not data:
                    break
            except OSError:
                break

    def send_keystrokes(self, keystrokes: str, wait_sec: float = 0.0) -> None:
        os.write(self.fd, keystrokes.encode("utf-8"))
        if wait_sec > 0:
            time.sleep(wait_sec)

    def __del__(self):
        self.running = False
        try:
            os.close(self.fd)
        except Exception:
            pass
        try:
            os.kill(self.pid, signal.SIGKILL)
            os.waitpid(self.pid, 0)
        except Exception:
            pass
