from pathlib import Path

class SplitFileReader:
    def __init__(self, resharded_dir):
        self.resharded_dir = Path(resharded_dir)
        self.chunk_index = 0
        self.current_file = None
        self.D = self._detect_D()
        self._open_next()

    def _detect_D(self):
        for p in self.resharded_dir.rglob('*.dat'):
            return len(p.relative_to(self.resharded_dir).parts)
        return 1

    def _get_chunk_path(self, i):
        temp = i
        digits = []
        for _ in range(self.D):
            digits.append(temp % 25)
            temp //= 25
        digits.reverse()
        curr = self.resharded_dir
        for d in digits[:-1]:
            curr = curr / str(d)
        return curr / f"{digits[-1]}.dat"

    def _open_next(self):
        if self.current_file:
            self.current_file.close()
            self.current_file = None
        path = self._get_chunk_path(self.chunk_index)
