import torch
import torch.distributed as dist

class _CopyToModelParallelRegion(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input):
        return input

    @staticmethod
    def backward(ctx, grad_output):
        grad_input = grad_output.clone()
        dist.all_reduce(grad_input)
        return grad_input

class _GatherForward(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input, dim=-1):
        ctx.dim = dim
        world_size = dist.get_world_size()

        input = input.contiguous()
        tensor_list = [torch.empty_like(input) for _ in range(world_size)]
        dist.all_gather(tensor_list, input)
        output = torch.cat(tensor_list, dim=dim)
        return output

    @staticmethod
    def backward(ctx, grad_output):
        world_size = dist.get_world_size()
        rank = dist.get_rank()
        dim = ctx.dim

        chunks = torch.chunk(grad_output, world_size, dim=dim)
        return chunks[rank].contiguous(), None

class _ReduceForward(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input):
        output = input.clone().contiguous()
        dist.all_reduce(output)
        return output

    @staticmethod
    def backward(ctx, grad_output):
        return grad_output

class ColumnParallelLinear(torch.nn.Module):
    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        world_size = dist.get_world_size()
        rank = dist.get_rank()

        assert out_features % world_size == 0
        self.out_features_per_partition = out_features // world_size

        my_weight = torch.chunk(master_weight, world_size, dim=0)[rank].contiguous()
        self.weight = torch.nn.Parameter(my_weight.clone())

        if bias:
            self.bias = torch.nn.Parameter(torch.zeros(
                self.out_features_per_partition,
                device=master_weight.device,
                dtype=master_weight.dtype
            ))
        else:
            self.register_parameter('bias', None)

    def forward(self, input):
        input_parallel = _CopyToModelParallelRegion.apply(input)
        output = torch.nn.functional.linear(input_parallel, self.weight, self.bias)
        output = _GatherForward.apply(output, -1)
        return output

class RowParallelLinear(torch.nn.Module):
    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        world_size = dist.get_world_size()
        rank = dist.get_rank()

        assert in_features % world_size == 0
        self.in_features_per_partition = in_features // world_size

        my_weight = torch.chunk(master_weight, world_size, dim=1)[rank].contiguous()
        self.weight = torch.nn.Parameter(my_weight.clone())

        if bias:
            self.bias = torch.nn.Parameter(torch.zeros(
                out_features,
                device=master_weight.device,
                dtype=master_weight.dtype
            ))
        else:
            self.register_parameter('bias', None)

    def forward(self, input):
        output = torch.nn.functional.linear(input, self.weight, None)
        output = _ReduceForward.apply(output)
        if self.bias is not None:
            output = output + self.bias
        return output
